import sys
from datetime import datetime

import click

ENVS = ["dev", "staging", "prod"]


@click.group()
@click.option("--env", type=click.Choice(ENVS), default="dev", envvar="PIPELINE_ENV",
              show_default=True, help="Target environment (or set PIPELINE_ENV).")
@click.option("--dry-run", is_flag=True, help="Plan without writing.")
@click.pass_context
def cli(ctx: click.Context, env: str, dry_run: bool) -> None:
    """Data pipeline runner."""
    ctx.ensure_object(dict)
    ctx.obj["env"] = env
    ctx.obj["dry_run"] = dry_run


@cli.command()
@click.argument("source")
@click.option("--date", type=click.DateTime(["%Y-%m-%d"]), default=str(datetime.today().date()))
@click.pass_context
def ingest(ctx: click.Context, source: str, date: datetime) -> None:
    """Run a single-day ingestion."""
    env, dry = ctx.obj["env"], ctx.obj["dry_run"]
    click.echo(f"[{env}] ingest source={source} date={date.date()} dry_run={dry}")


@cli.command()
@click.argument("source")
@click.option("--start", type=click.DateTime(["%Y-%m-%d"]), required=True)
@click.option("--end", type=click.DateTime(["%Y-%m-%d"]), required=True)
@click.pass_context
def backfill(ctx: click.Context, source: str, start: datetime, end: datetime) -> None:
    """Reprocess an inclusive date range."""
    if end < start:
        raise click.BadParameter("--end must not be before --start", param_hint="--end")
    env, dry = ctx.obj["env"], ctx.obj["dry_run"]
    days = (end - start).days + 1
    click.echo(f"[{env}] backfill {source}: {days} day(s) dry_run={dry}")


if __name__ == "__main__":
    cli()
